// Generated by Cypress Author on 2026-10-02.
import { mountWorkspace, mockRefresh, task } from "../../support/tasks";

describe("Create tasks", () => {
  beforeEach(() => {
    mountWorkspace();
    cy.get("[data-task-create]").click();
    cy.get("dialog[open]").should("be.visible");
  });

  it("creates a task → closes the dialog and refreshes the list", () => {
    const created = task({ title: "Plan release", description: "Prepare checklist" });
    cy.intercept("POST", "/api/tasks", { statusCode: 201, body: created }).as("createTask");
    mockRefresh([created]);

    cy.get("#task-title").type(created.title);
    cy.get("#task-description").type(created.description);
    cy.contains("dialog button", "Create task").click();

    cy.wait("@createTask").its("request.body").should("deep.equal", {
      title: created.title, description: created.description,
    });
    cy.wait("@refreshTasks");
    cy.get("dialog").should("not.exist");
    cy.get('[role="status"]').should("have.text", "Task created.");
    cy.get('section[aria-label="Task list"]').should("have.attr", "aria-busy", "false")
      .and("contain.text", created.title).and("contain.text", created.description);
    cy.get("@createTask.all").should("have.length", 1);
  });

  it("submits an empty title → blocks creation before any API call", () => {
    cy.intercept("POST", "/api/tasks", { statusCode: 201, body: task() }).as("createTask");
    cy.contains("dialog button", "Create task").click();
    cy.get("#task-title").should("match", ":invalid");
    cy.get("dialog[open]").should("be.visible");
    cy.get("@createTask.all").should("have.length", 0);
  });

  it("receives validation errors → preserves input and allows a corrected retry", () => {
    cy.intercept("POST", "/api/tasks", {
      statusCode: 400,
      body: { message: "Check your task.", errors: { title: ["Title is required."] } },
    }).as("invalidTask");
    cy.get("#task-title").type("   ");
    cy.get("#task-description").type("Keep these details");
    cy.contains("dialog button", "Create task").click();
    cy.wait("@invalidTask");
    cy.get('dialog [role="alert"]').should("have.text", "Check your task.");
    cy.get("#task-title").should("have.attr", "aria-invalid", "true");
    cy.get("#task-title-error").should("have.text", "Title is required.");
    cy.get("#task-description").should("have.value", "Keep these details");

    const created = task({ title: "Valid title", description: "Keep these details" });
    cy.intercept("POST", "/api/tasks", { statusCode: 201, body: created }).as("createTask");
    mockRefresh([created]);
    cy.get("#task-title").clear().type(created.title);
    cy.contains("dialog button", "Create task").click();
    cy.wait("@createTask").its("request.body").should("deep.equal", {
      title: created.title, description: created.description,
    });
    cy.wait("@refreshTasks");
    cy.get("dialog").should("not.exist");
    cy.contains('section[aria-label="Task list"] h2', created.title).should("be.visible");
  });

  // Generated by Cypress Author on 2026-10-02.
  it("fills only the title → uses priority 3 and no due date", () => {
    const created = task({ title: "Minimal task", description: "" });
    cy.intercept("POST", "/api/tasks", { statusCode: 201, body: created }).as("createTask");
    mockRefresh([created]);
    cy.get("#task-priority").should("have.value", "3");
    cy.get("#task-due-date").should("have.value", "");
    cy.get("#task-title").type(created.title);
    cy.contains("dialog button", "Create task").click();
    cy.wait("@createTask").its("request.body").should("deep.equal", { title: created.title, description: "" });
    cy.wait("@refreshTasks");
    cy.get('section[aria-label="Task list"] li').should("contain.text", "Priority 3").and("not.contain.text", "Due");
    cy.contains('section[aria-label="Task list"] h2', created.title).click();
    cy.get("dialog").should("contain.text", "No due date.");
  });

  // Generated by Cypress Author on 2026-10-02.
  for (const priority of [1, 2, 4]) {
    it(`sets priority ${priority} and a due date → submits and displays both values`, () => {
      const created = task({ title: "Scheduled task", description: "", priority, dueDate: "2026-11-12" });
      cy.intercept("POST", "/api/tasks", { statusCode: 201, body: created }).as("createTask");
      mockRefresh([created]);
      cy.get("#task-title").type(created.title);
      cy.get("#task-priority").select(String(priority));
      cy.get("#task-due-date").type(created.dueDate!);
      cy.contains("dialog button", "Create task").click();
      cy.wait("@createTask").its("request.body").should("deep.equal", {
        title: created.title, description: "", priority, dueDate: created.dueDate,
      });
      cy.wait("@refreshTasks");
      cy.get('section[aria-label="Task list"] li').should("contain.text", `Priority ${priority}`)
        .and("contain.text", `Due ${created.dueDate}`);
      cy.contains('section[aria-label="Task list"] h2', created.title).click();
      cy.get(`dialog time[datetime="${created.dueDate}"]`).should("have.text", created.dueDate);
      cy.contains("dialog button", "Edit task").click();
      cy.get("#task-priority").should("have.value", String(priority));
      cy.get("#task-due-date").should("have.value", created.dueDate);
    });
  }

  // Generated by Cypress Author on 2026-10-02.
  it("receives optional field errors → preserves values and allows a corrected retry", () => {
    cy.intercept("POST", "/api/tasks", {
      statusCode: 400,
      body: { message: "Please check the task fields.", errors: {
        priority: ["Choose a priority from 1 to 4."], dueDate: ["Provide a valid due date."],
      } },
    }).as("invalidTask");
    cy.get("#task-title").type("Scheduled task");
    cy.get("#task-priority").select("1");
    cy.get("#task-due-date").type("2026-11-12");
    cy.contains("dialog button", "Create task").click();
    cy.wait("@invalidTask");
    cy.get("#task-priority").should("have.value", "1").and("have.attr", "aria-invalid", "true");
    cy.get("#task-due-date").should("have.value", "2026-11-12").and("have.attr", "aria-invalid", "true");
    cy.get("#task-priority-error").should("have.text", "Choose a priority from 1 to 4.");
    cy.get("#task-due-date-error").should("have.text", "Provide a valid due date.");
    const created = task({ title: "Scheduled task", description: "", priority: 2, dueDate: "2026-11-13" });
    cy.intercept("POST", "/api/tasks", { statusCode: 201, body: created }).as("createTask");
    mockRefresh([created]);
    cy.get("#task-priority").select("2");
    cy.get("#task-due-date").clear().type(created.dueDate!);
    cy.contains("dialog button", "Create task").click();
    cy.wait("@createTask").its("request.body").should("deep.equal", {
      title: created.title, description: "", priority: 2, dueDate: created.dueDate,
    });
    cy.wait("@refreshTasks");
    cy.get("dialog").should("not.exist");
  });
});
